namespace ModularAudience.Audio.Effects;

/// <summary>Ordered exactly as the waveform menu. Every named effect has real, separate DSP routing.</summary>
public static class AudioEffectCatalog
{
    private static EffectParameter N(string key, string label, double min, double max, double value, double step = 1,
        bool integral = false, string description = "") => new(key, label, min, max, value, step, integral, Description: description);
    private static EffectParameter B(string key, string label, bool value, string description = "") =>
        new(key, label, 0, 1, value ? 1 : 0, Integral: true, Kind: EffectParameterKind.Boolean, Description: description);
    private static EffectParameter C(string key, string label, int value, params string[] choices) =>
        new(key, label, 0, choices.Length - 1, value, Integral: true, Kind: EffectParameterKind.Choice, Choices: Array.AsReadOnly(choices));
    private static EffectParameter[] Mix(params EffectParameter[] parameters) => [.. parameters,
        N("WetPercent", "Wet / dry (%)", 0, 100, 35), N("OutputGainDb", "Output gain (dB)", -48, 24, 0, 0.1)];
    private static EffectParameter[] Reverb(double decay, double wet) => [
        N("DecaySeconds", "Decay / RT60 (s)", 0.1, 20, decay, 0.1),
        N("SizePercent", "Space / delay size (%)", 25, 200, 100),
        N("PreDelayMs", "Pre-delay (ms)", 0, 250, 12, 0.1),
        N("DampingHz", "High-frequency damping (Hz)", 500, 20000, 6500, 100),
        N("DiffusionPercent", "Diffusion (%)", 0, 100, 75),
        N("TailSeconds", "Append tail (s; 0 = crop)", 0, 30, Math.Round(decay * 1.25, 1), 0.1,
            description: "The tail is inserted before subsequent audio, not mixed over it. 0 keeps the region's original length."),
        N("WetPercent", "Wet / dry (%)", 0, 100, wet), N("OutputGainDb", "Output gain (dB)", -48, 24, 0, 0.1)];
    private static EffectParameter[] Delay(double time, double feedback, double wet) => [
        N("DelayMs", "Delay / tap spacing (ms)", 1, 2000, time, 0.1),
        N("FeedbackPercent", "Feedback (%)", 0, 95, feedback),
        N("LowPassHz", "Echo low-pass (Hz)", 200, 20000, 10000, 100),
        N("TailSeconds", "Append tail (s; 0 = crop)", 0, 30, 2, 0.1),
        N("WetPercent", "Wet / dry (%)", 0, 100, wet), N("OutputGainDb", "Output gain (dB)", -48, 24, 0, 0.1)];
    private static EffectParameter[] Dynamics(bool compressor) => Mix(
        N("ThresholdDb", "Threshold (dBFS)", -90, 0, compressor ? -18 : -45, 0.5),
        N("Ratio", "Ratio", 1, 20, compressor ? 4 : 3, 0.1),
        N("AttackMs", "Attack (ms)", 0.05, 200, compressor ? 10 : 2, 0.1),
        N("ReleaseMs", "Release (ms)", 1, 3000, 120),
        N("KneeDb", "Soft knee (dB)", 0, 24, compressor ? 6 : 0, 0.5),
        N("MakeupDb", "Make-up gain (dB)", -24, 24, compressor ? 3 : 0, 0.1),
        N("RangeDb", "Maximum attenuation (dB)", 6, 96, 72),
        N("HoldMs", "Gate hold (ms)", 0, 1000, 35));

    public static IReadOnlyList<AudioEffectDefinition> All { get; } = Array.AsReadOnly(Create());
    public static AudioEffectDefinition Get(AudioEffectKind kind) => All.FirstOrDefault(effect => effect.Kind == kind)
        ?? throw new ArgumentOutOfRangeException(nameof(kind));

